import { getErrorMessage } from '../utils/error'

const { t } = useI18n()
const toast = inject<{ error: (m: string) => void; success: (m: string) => void }>('toast')!

const props = defineProps<{ initialSection?: string }>()

// harness（DeepSeek Harness）是特殊的「集成」分类，不属于 RuntimeAdapter 多版本模型，
// 直接在环境管理内复用 SettingsDSH 组件承载安装/配置/服务/插件/更新。
const HARNESS_KEY = 'harness'
const HTTP_KEY = 'httpserve'
const isHarness = computed(() => selectedId.value === HARNESS_KEY)
const isHttp = computed(() => selectedId.value === HTTP_KEY)

// 侧边栏分组（按功能合并）：语言运行时 / Web 服务 / 数据库 / 缓存与存储 / 开发工具。
// 缓存与存储组聚合原「缓存」(redis/memcached) 与对象存储 (minio)；工具组追加 harness 与 HTTP 服务两个特殊入口。
const GROUP_ORDER = ['language', 'webserver', 'database', 'storage', 'tool']
const GROUP_LABEL: Record<string, string> = {
  language: 'groupLanguage',
  webserver: 'groupWebserver',
  database: 'groupDatabase',
  storage: 'groupStorage',
  tool: 'groupTool',
}

// 分组展开/收起状态（持久化到 localStorage）
const COLLAPSE_KEY = 'quickdock.env.collapsedGroups'
const collapsedGroups = reactive<Record<string, boolean>>(loadCollapsedGroups())
function loadCollapsedGroups(): Record<string, boolean> {
  try {
    const raw = localStorage.getItem(COLLAPSE_KEY)
    if (raw) return JSON.parse(raw) as Record<string, boolean>
  } catch (e) {
    console.warn('[env] 读取/保存分组折叠状态失败', e)
  }
  return {}
}
function toggleGroup(key: string) {
  collapsedGroups[key] = !collapsedGroups[key]
  try {
    localStorage.setItem(COLLAPSE_KEY, JSON.stringify(collapsedGroups))
  } catch (e) {
    console.warn('[env] 读取/保存分组折叠状态失败', e)
  }
}

interface SidebarItem {
  kind: 'runtime' | 'special'
  id: string
  name: string
  avatar: string
  color: string
  count?: number
  running?: boolean
  active: boolean
}
const sidebarGroups = computed(() => {
  const out: { key: string; labelKey: string; items: SidebarItem[]; collapsed: boolean }[] = []
  for (const g of GROUP_ORDER) {
    if (collapsedGroups[g]) {
      // 折叠态：仅保留分组标题，列表项清空
      out.push({ key: g, labelKey: GROUP_LABEL[g], items: [], collapsed: true })
      continue
    }
    const items: SidebarItem[] = runtimes.value
      .filter((r) => r.group === g)
      .map((r): SidebarItem => ({
        kind: 'runtime',
        id: r.id,
        name: r.name,
        avatar: avatarIcon(r.id),
        color: avatarColor(r.id),
        count: r.installed.length,
        running: r.hasService && anyRunning(r),
        active: selectedId.value === r.id,
      }))
      // 各分类下按名称首字母排序，保证展示稳定有序
      .sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' }))
    if (g === 'tool') {
      items.push({ kind: 'special', id: HARNESS_KEY, name: t('navDsh'), avatar: 'DS', color: 'var(--color-accent)', active: isHarness.value })
      items.push({ kind: 'special', id: HTTP_KEY, name: t('httpServe'), avatar: '⬡', color: '#4a9eff', active: isHttp.value })
    }
    if (items.length) out.push({ key: g, labelKey: GROUP_LABEL[g], items, collapsed: false })
  }
  return out
})

interface SourceInfo {
  id: string
  name: string
}
interface Install {
  version: string
  scope: string // portable | system
  path: string
  active: boolean // 是否为环境变量指向的激活版本
  inSystemPath: boolean // 该版本 bin 目录是否真正在系统 PATH 中（后端读取 PATH 比对得出）
  alias: string // 用户别名
  note: string // 用户备注
}
interface ServiceStatus {
  running: boolean
  pid: number
  port: number
  version: string
}
interface RuntimeInfo {
  id: string
  name: string
  group: string
  platforms: string[]
  recommended: string[]
  installed: Install[]
  sources: SourceInfo[]
  activeSource: string
  hasService: boolean
  hasLog: boolean
  webConsolePort: number
}

