  { id: 'caddy', name: 'Caddy', group: 'webserver', hasService: true },
  { id: 'traefik', name: 'Traefik', group: 'webserver', hasService: true },
  { id: 'redis', name: 'Redis', group: 'storage', hasService: true },
  { id: 'memcached', name: 'Memcached', group: 'storage', hasService: true },
  { id: 'mariadb', name: 'MariaDB', group: 'database', hasService: true },
  { id: 'mysql', name: 'MySQL', group: 'database', hasService: true },
  { id: 'postgresql', name: 'PostgreSQL', group: 'database', hasService: true },
  { id: 'mongodb', name: 'MongoDB', group: 'database', hasService: true },
  { id: 'minio', name: 'MinIO', group: 'storage', hasService: true },
  { id: 'rabbitmq', name: 'RabbitMQ', group: 'storage', hasService: true },
  { id: 'git', name: 'Git', group: 'tool', hasService: false },
  { id: 'composer', name: 'Composer', group: 'tool', hasService: false },
  { id: 'ffmpeg', name: 'FFmpeg', group: 'tool', hasService: false },
  { id: 'mailpit', name: 'Mailpit', group: 'tool', hasService: true },
  { id: 'frpc', name: 'frpc', group: 'tool', hasService: false },
  { id: 'gh', name: 'GitHub CLI', group: 'tool', hasService: false },
  { id: 'mkcert', name: 'mkcert', group: 'tool', hasService: false },
  { id: 'python', name: 'Python', group: 'language', hasService: false },
  { id: 'apache', name: 'Apache', group: 'webserver', hasService: true },
  { id: 'ftp', name: 'FTP', group: 'webserver', hasService: true },
]
function staticRuntime(s: typeof STATIC_CATALOG[number]): RuntimeInfo {
  return {
    id: s.id, name: s.name, group: s.group,
    platforms: [], recommended: [],
    installed: [], sources: [], activeSource: '',
    hasService: s.hasService, hasLog: false, webConsolePort: 0,
  }
}
const runtimes = ref<RuntimeInfo[]>(STATIC_CATALOG.map(staticRuntime))
const selectedId = ref<string>(props.initialSection || STATIC_CATALOG[0].id)
// 首次 EnvList 返回前不渲染「未安装版本」空状态：页面重挂载时数据从后端检测结果缓存
// 毫秒级回填，但仍有一个异步帧的空窗，避免空状态闪现后又被版本表替换。
const loadedOnce = ref(false)

const selected = computed<RuntimeInfo | null>(() => {
  return runtimes.value.find((r) => r.id === selectedId.value) || runtimes.value[0] || null
})

// 每个运行时的交互态，按 id 索引
interface UiState {
  version: string
  source: string
  custom: string
  installing: boolean
  stage: string
  message: string
  error: boolean          // message 是否为错误（红色样式 + 可复制）
  written: number
  total: number
  speed: number            // 下载速度（字节/秒），用于显示
  eta: number              // 预计剩余秒数，用于显示
  available: string[]      // 已获取的可选版本列表（加载后）
  fetching: boolean        // 正在拉取版本列表
  loadError: string        // 拉取失败时的错误信息（空=无错误）
  listExpanded: boolean    // 版本列表是否展开（点击 ▾ 切换）
  svc: Record<string, ServiceStatus>
}
const ui = reactive<Record<string, UiState>>({})

// 端口冲突探测结果（按运行时 id 索引）：后端 EnvPortConflict 返回默认服务端口是否被其它程序占用。
interface PortConflict {
  occupied: boolean
  port: number
  pid: number
  image: string
  ours: boolean // 占用者是否就是本会话拉起的该运行时
}
const portConflicts = reactive<Record<string, PortConflict>>({})

// PATH 可视化面板：聚合所有已激活运行时的 bin 目录及其在系统 PATH 中的状态
const pathModal = reactive<{ open: boolean }>({ open: false })
function binDirOf(ins: any): string {
  if (ins.scope === 'system') {
    const parts = (ins.path || '').split(/[\\/]/)
    parts.pop()
    return parts.join('/')
  }
  return ins.path || ''
}
const pathEntries = computed(() => {
  const out: { id: string; name: string; version: string; binDir: string; inPath: boolean }[] = []
  for (const r of runtimes.value) {
    if (!r.installed) continue
    for (const ins of r.installed) {
      if (ins.active) {
        out.push({ id: r.id, name: r.name, version: ins.version, binDir: binDirOf(ins), inPath: !!ins.inSystemPath })
      }
    }
  }
  return out
})

// 端口全景：聚合所有运行中服务的运行时 / 版本 / 服务端口 / 控制台端口。
const panorama = reactive<{ open: boolean }>({ open: false })
// 打开端口全景前，预取各 RabbitMQ 版本的管理后台状态，使「控制台」列准确（其余运行时端口为静态常量，无需探测）。
function openPanorama() {
  panorama.open = true
  for (const r of runtimes.value) {
    if (r.id !== 'rabbitmq') continue
    for (const ins of (r.installed || [])) {
      if (rabbitMgmt[ins.version] === undefined) fetchMgmt(ins.version)
    }
  }
}
const panoramaEntries = computed(() => {
  const out: { id: string; name: string; version: string; port: number; consolePort: number }[] = []
  for (const r of runtimes.value) {
    if (!r.hasService) continue
    for (const ins of (r.installed || [])) {
      if (!svcOn(r, ins.version)) continue
      out.push({ id: r.id, name: r.name, version: ins.version, port: svcPort(r, ins.version), consolePort: consolePort(r, ins) })
    }
  }
  return out
})

// 当前选中运行时的端口冲突（无探测结果时返回零值）
const selectedConflict = computed<PortConflict | null>(() => {
  return portConflicts[selectedId.value] || null
})

function stateFor(id: string, info: RuntimeInfo): UiState {
  if (!ui[id]) {
    ui[id] = {
      version: '',
      source: '',
      custom: '',
      installing: false,
      stage: '',
      message: '',
      error: false,
      written: 0,
      total: -1,
      speed: 0,
      eta: 0,
      available: [],
      fetching: false,
      loadError: '',
      listExpanded: false,
      svc: {},
    }
  }
  const s = ui[id]
  // 静态目录首建时 activeSource 还是空，EnvList 合并后回填一次。
  // 版本号不在此默认（避免一进面板就显示推荐版本）：上游拉取成功后由 loadAvailable 填最新版本，拉取失败则保持空。
  if (!s.source && (info.activeSource || info.sources[0]?.id)) {
    s.source = info.activeSource || info.sources[0]?.id || ''
  }
  return s
}

// failState 把运行时的错误持久化到可复制的 .env-msg 区域（toast 仅作瞬时提示），避免报错一闪而过且无法复制。
function failState(r: RuntimeInfo, e: any) {
  const s = stateFor(r.id, r)
  s.message = getErrorMessage(e)
  s.error = true
  s.installing = false
  toast.error(s.message)
}

// versionInput: 绑定到当前选中运行时的版本号，读写都经过 ui[state] 保证一致性
const versionInput = computed({
  get() { return stateFor(selectedId.value, selected.value!).version },
  set(v: string) { stateFor(selectedId.value, selected.value!).version = v },
})

// currentRuntimeState: 当前选中运行时的 UI 状态，模板中复用避免重复调用 stateFor
const currentRuntimeState = computed(() => {
  const r = selected.value
  return r ? stateFor(r.id, r) : null
})

function percent(s: { written: number; total: number }): number {
  if (s.total <= 0) return -1
  return Math.min(100, Math.floor((s.written / s.total) * 100))
}
function formatSpeed(b: number): string {
  if (!isFinite(b) || b <= 0) return ''
  if (b >= 1048576) return (b / 1048576).toFixed(1) + ' MB/s'
  if (b >= 1024) return (b / 1024).toFixed(0) + ' KB/s'
  return b.toFixed(0) + ' B/s'
}
function formatEta(sec: number): string {
  if (!isFinite(sec) || sec <= 0) return ''
  if (sec >= 3600) return (sec / 3600).toFixed(1) + ' h'
  if (sec >= 60) return Math.ceil(sec / 60) + ' min'
  return Math.ceil(sec) + ' s'
}

function svcOn(r: RuntimeInfo, version: string): boolean {
  const st = ui[r.id]?.svc?.[version]
  return !!(st && st.running)
}
function svcPort(r: RuntimeInfo, version: string): number {
  return ui[r.id]?.svc?.[version]?.port || 0
}
function anyRunning(r: RuntimeInfo): boolean {
  return r.installed.some((ins) => svcOn(r, ins.version))
}

// 别名/备注编辑弹窗
interface EditState {
  open: boolean
  runtime: string
  version: string
  alias: string
  note: string
}
const editing = reactive<EditState>({
  open: false,
  runtime: '',
  version: '',
  alias: '',
  note: '',
})
function openAlias(r: RuntimeInfo, ins: Install) {
  editing.open = true
  editing.runtime = r.id
  editing.version = ins.version
  editing.alias = ins.alias || ''
  editing.note = ins.note || ''
}
async function saveAlias() {
  try {
    unwrap(await EnvSetMeta(editing.runtime, editing.version, editing.alias.trim(), editing.note.trim()))
    toast.success(t('saved'))
    editing.open = false
    await load()
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}

// 设置/取消环境变量：未设置的版本注册其 bin 目录到系统 PATH；已设置的注销其 bin 目录。
// 取消走 EnvUnsetActive（直接按版本注销，不依赖 active 元数据），避免元数据漂移导致 PATH 残留旧版本。
async function toggleEnvVar(r: RuntimeInfo, ins: Install) {
  try {
    if (ins.inSystemPath) {
      unwrap(await EnvUnsetActive(r.id, ins.version))
    } else {
      unwrap(await EnvSetActive(r.id, ins.version))
    }
    await load()
  } catch (e: any) {
    failState(r, e)
  }
}

// 操作列下拉菜单（设置别名 / 删除 收纳于此）
const openMenu = ref<string | null>(null)
function toggleMenu(v: string) {
  const willOpen = openMenu.value !== v
  openMenu.value = willOpen ? v : null
  // 展开 RabbitMQ 操作菜单时，拉取管理后台启用状态以决定显示「启用/关闭」
  if (willOpen && selected.value?.id === 'rabbitmq') {
    const ins = selected.value.installed.find(i => i.version === v)
    if (ins) fetchMgmt(ins.version)
  }
}

// 删除确认弹窗（替换原生 confirm，统一风格）
const confirmDelete = reactive<{ open: boolean; runtime: string; version: string; scope: string; removeData: boolean }>({
  open: false,
  runtime: '',
  version: '',
  scope: '',
  removeData: false,
})
// 卸载时可选择性清理数据目录的运行时（这些 runtime 实现了 DataDirProvider）
const HAS_DATA_DIR = new Set(['postgresql', 'mariadb', 'mysql', 'mongodb', 'minio', 'mailpit'])
function askDelete(r: RuntimeInfo, ins: Install) {
  if (ins.scope === 'system') {
    toast.error(t('systemCannotDelete'))
    return
  }
  confirmDelete.runtime = r.id
  confirmDelete.version = ins.version
  confirmDelete.scope = ins.scope
  confirmDelete.removeData = false
  confirmDelete.open = true
  openMenu.value = null
}
async function doDelete() {
  try {
    unwrap(await EnvDeleteVersion(confirmDelete.runtime, confirmDelete.version, confirmDelete.removeData))
    toast.success(t('deleted'))
    confirmDelete.open = false
    await load()
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}

// 导入已有安装：选择外部目录 → 探测版本号并登记，使其在版本列表中可见。
async function importExisting(r: RuntimeInfo) {
  try {
    const dir = unwrap<string | null>(await PickFolderPath(t('pickDirTitle')))
    if (!dir) return
    const version = unwrap<string>(await EnvImportVersion(r.id, dir))
    toast.success(t('imported') + ' ' + r.name + ' ' + version)
    await load()
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}

// 在文件资源管理器中打开路径（目录直接打开，文件高亮选中）。
async function reveal(path: string) {
  if (!path) return
  try {
    unwrap(await RevealInExplorer(path))
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}

// ---- PHP 配置弹窗（php.ini / 禁用函数 / 错误日志 / 扩展）----
interface PHPExt { name: string; file: string; enabled: boolean }
const phpModal = reactive<{
  open: boolean; runtime: string; version: string; tab: string
  raw: string; disableFunctions: string; errorLog: string; errorLogContent: string
  extensions: PHPExt[]
}>({
  open: false, runtime: '', version: '', tab: 'ini',
  raw: '', disableFunctions: '', errorLog: '', errorLogContent: '', extensions: [],
})
async function openPHPConfig(r: RuntimeInfo, ins: Install, tab: string) {
  try {
    const cfg = unwrap<any>(await EnvPHPConfigGet(r.id, ins.version))
    phpModal.runtime = r.id
    phpModal.version = ins.version
    phpModal.tab = tab
    phpModal.raw = cfg.raw || ''
    phpModal.disableFunctions = cfg.disableFunctions || ''
    phpModal.errorLog = cfg.errorLog || ''
    phpModal.errorLogContent = cfg.errorLogContent || ''
    phpModal.extensions = (cfg.extensions || []).map((e: any) => ({ name: e.name, file: e.file, enabled: !!e.enabled }))
    phpModal.open = true
    openMenu.value = null
  } catch (e: any) {
    toast.error(getErrorMessage(e))
  }
}
function toggleExt(i: number) {
  phpModal.extensions[i].enabled = !phpModal.extensions[i].enabled
}
async function savePHPConfig() {
  try {
    const patch: any = {}
    if (phpModal.tab === 'ini') {
      patch.raw = phpModal.raw
    } else {
